import gzip,glob,re
from pypdf import PdfReader
for f in sorted(glob.glob('studies/papers/*')):
 t='\n'.join(p.extract_text() for p in PdfReader(f).pages)
 print('\n###',f)
 for m in re.finditer(r'(?i)tamoxifen|4.?OHT|hydroxytam|4.?HT',t):
  print(t[max(0,m.start()-180):m.end()+230].replace('\n',' '))
